window.kbPageData["views/entry/k-51fd3be46fe3b710"] = {"key":"entry/k-51fd3be46fe3b710","state":{"route":"entry/k-51fd3be46fe3b710"},"node":{"id":"k-51fd3be46fe3b710","mode":"k","title":"纪念中国工农红军长征胜利 90 周年大会（10 月）","type":"事实与事件","domain":"历史","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["culture"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["历史"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"纪念中国工农红军长征胜利 90 周年大会（10 月）","slug":"82db21433787"}],"directorySummary":"考点四十二 纪念中国工农红军长征胜利 90 周年大会（10 月）\n纪念中国工农红军长征胜利 90 周年大会隆重举行。从 1934 年 10 月至 1936 年 10 月，我们党\n领导红军第一、第二、第四方面军和第二十五军，进行了震撼世界、彪炳史册的伟大长征。红\n军长征纵横十余省，长驱二万五千里，跨越…","sources":[{"id":"4d987c83191ff402","label":"纪念中国工农红军长征胜利 90 周年大会（10 月）","topic":"重要会议讲话","category":"时政","text":"考点四十二 纪念中国工农红军长征胜利 90 周年大会（10 月）\n纪念中国工农红军长征胜利 90 周年大会隆重举行。从 1934 年 10 月至 1936 年 10 月，我们党\n领导红军第一、第二、第四方面军和第二十五军，进行了震撼世界、彪炳史册的伟大长征。红\n军长征纵横十余省，长驱二万五千里，跨越近百条江河，翻越皑皑雪山，穿过茫茫草地，进行\n600 余次战役战斗，粉碎上百万敌军围追堵截，胜利实现北上抗日的战略转移，成功开创了中\n国革命新局面。\n讲话深刻阐述了红军长征的制胜之道：一是依靠党的正确领导，1935 年 1 月遵义会议事实上\n确立了毛泽东同志在党中央和红军的领导地位，在最危急关头挽救了党、挽救了红军、挽救了\n中国革命；二是依靠坚定的革命意志；三是依靠独立自主、实事求是；四是依靠广大人民群众\n支持，长征一路宣传了党的主张，播撒下革命火种。\n伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信\n念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺\n牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪\n律、紧密团结的精神；就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的\n精神。伟大长征精神作为中国共产党人精神谱系的重要组成部分，跨越时空、历久弥新。新征\n程是党和人民的新长征，要大力弘扬伟大长征精神，同心协力走好新的长征路。","source":{"doc":"4e539a366dce19555ccf","first":10,"last":10,"page":10,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"culture","title":"文化传承与创新表达"}],"units":{"k-51fd3be46fe3b710":[]}};
